Brief: Tell me how MangoDB evaluates a find query with a filter. — about getBSONTypeCode (src/query-matcher.ts)

1. * Get the BSON type code for a JavaScript value.
2. export function getBSONTypeCode(value: unknown): number {
3. if (value === undefined) return BSON_TYPE_ALIASES.undefined;
4. if (value === null) return BSON_TYPE_ALIASES.null;
5. if (typeof value === 'string') return BSON_TYPE_ALIASES.string;
6. if (typeof value === 'boolean') return BSON_TYPE_ALIASES.bool;
7. if (typeof value === 'number') {
8. // In JavaScript, we can distinguish integers from floats
9. return Number.isInteger(value) ? BSON_TYPE_ALIASES.int : BSON_TYPE_ALIASES.double;
10. if (Array.isArray(value)) return BSON_TYPE_ALIASES.array;
11. if (value instanceof Date) return BSON_TYPE_ALIASES.date;
12. if (value instanceof RegExp) return BSON_TYPE_ALIASES.regex;

